#!/usr/bin/env bash
# Regenerate the committed fixtures in testdata/generated/ with real tools.
#
#   testdata/gen.sh
#
# Everything is produced by openssl (3.x) and keytool (JDK 17+) run on this
# machine; nothing in generated/ is hand-edited. Private keys are created in a
# scratch directory that is deleted on exit and never copied into generated/.
# The committed stores are trust stores (trustedCertEntry / -nokeys style), so
# they contain no private key material either.
#
# generated/README.md records the tool versions and the trustinspector commit
# the fixtures were produced against.
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="$HERE/generated"
SCRATCH="$(mktemp -d)"
trap 'rm -rf "$SCRATCH"' EXIT
P="$SCRATCH"

mkdir -p "$OUT"
# Idempotent: keytool refuses to import into an existing keystore. The
# report-1 baseline (report-1-rootfs.json) is NOT touched here; it is pinned
# and only regenerated by capture-report-1.sh.
rm -f "$OUT"/demo-* 2>/dev/null || true
: > "$OUT/.keep"


OPENSSL=${OPENSSL:-openssl}
KEYTOOL=${KEYTOOL:-keytool}
echo "using $($OPENSSL version), $($KEYTOOL -helpversion 2>&1 | head -1 || $KEYTOOL -version 2>&1 | head -1 || echo keytool)"

# --- demo PKI: root A, root B, one intermediate key certified by both (the
# cross-signed twins), and a leaf issued by the intermediate. ---------------
ca() { # ca <name> <subject>
  $OPENSSL req -x509 -newkey rsa:2048 -nodes -keyout "$P/$1.key" -out "$P/$1.crt" \
    -days 3650 -subj "$2" \
    -addext "basicConstraints=critical,CA:TRUE" \
    -addext "keyUsage=critical,keyCertSign,cRLSign" \
    -addext "subjectKeyIdentifier=hash" 2>/dev/null
}
ca rootA "/O=Inspector Test/CN=Inspector Root A"
ca rootB "/O=Other Inspector/CN=Inspector Root B"

$OPENSSL genrsa -out "$P/int.key" 2048 2>/dev/null
$OPENSSL req -new -key "$P/int.key" -subj "/O=Inspector Test/CN=Inspector Issuing CA" -out "$P/int.csr"
cat > "$P/int.ext" <<'EOF'
basicConstraints=critical,CA:TRUE,pathlen:0
keyUsage=critical,keyCertSign,cRLSign
extendedKeyUsage=serverAuth,clientAuth
subjectKeyIdentifier=hash
authorityKeyIdentifier=keyid
authorityInfoAccess=caIssuers;URI:http://ca.inspector.test/root.crt
crlDistributionPoints=URI:http://ca.inspector.test/root.crl
certificatePolicies=2.23.140.1.2.1
EOF
$OPENSSL x509 -req -in "$P/int.csr" -CA "$P/rootA.crt" -CAkey "$P/rootA.key" -CAcreateserial \
  -days 1825 -extfile "$P/int.ext" -out "$P/intA.crt" 2>/dev/null
$OPENSSL x509 -req -in "$P/int.csr" -CA "$P/rootB.crt" -CAkey "$P/rootB.key" -CAcreateserial \
  -days 1825 -extfile "$P/int.ext" -out "$P/intB.crt" 2>/dev/null

$OPENSSL req -new -newkey rsa:2048 -nodes -keyout "$P/leaf.key" -subj "/CN=leaf.inspector.test" \
  -out "$P/leaf.csr" 2>/dev/null
cat > "$P/leaf.ext" <<'EOF'
basicConstraints=critical,CA:FALSE
keyUsage=critical,digitalSignature
extendedKeyUsage=serverAuth
subjectAltName=DNS:leaf.inspector.test,DNS:alt.inspector.test
authorityKeyIdentifier=keyid
EOF
$OPENSSL x509 -req -in "$P/leaf.csr" -CA "$P/intA.crt" -CAkey "$P/int.key" -CAcreateserial \
  -days 90 -extfile "$P/leaf.ext" -out "$P/leaf.crt" 2>/dev/null

# A negative-serial certificate: Go's x509.ParseCertificate rejects these, so
# the fixture pins that behavior for the parser tests.
$OPENSSL req -new -x509 -newkey rsa:2048 -nodes -keyout "$P/neg.key" -out "$P/neg.crt" \
  -days 30 -subj "/CN=Inspector Negative Serial" -set_serial -42 2>/dev/null
cp "$P/neg.crt" "$OUT/demo-negative-serial.crt"

# --- single certificates and the cross-signed twin -------------------------
cp "$P/rootA.crt" "$OUT/demo-root.crt"
cp "$P/intA.crt" "$OUT/demo-intermediate.crt"
cp "$P/intB.crt" "$OUT/demo-cross-signed.crt"
cp "$P/leaf.crt" "$OUT/demo-leaf.crt"
$OPENSSL x509 -in "$P/leaf.crt" -outform DER -out "$OUT/demo-leaf.der"

# --- PEM bundle (root + intermediate + leaf) -------------------------------
cat "$P/rootA.crt" "$P/intA.crt" "$P/leaf.crt" > "$OUT/demo-bundle.pem"

# --- TRUSTED CERTIFICATE bundles ------------------------------------------
# Plain CERTIFICATE followed by a TRUSTED CERTIFICATE carrying a serverAuth
# reject (OpenSSL X509_CERT_AUX). See crypto/x509/x_x509a.c in OpenSSL.
cat "$P/rootA.crt" > "$OUT/demo-trusted-reject.pem"
$OPENSSL x509 -in "$P/intA.crt" -trustout -addreject serverAuth \
  -setalias "inspector-int" -out "$P/int-reject.trust" 2>/dev/null
cat "$P/int-reject.trust" >> "$OUT/demo-trusted-reject.pem"
# A trusted certificate with an alias but no trust/reject entries.
$OPENSSL x509 -in "$P/rootB.crt" -trustout -setalias "inspector-root-b" \
  -out "$OUT/demo-trusted-alias.pem" 2>/dev/null

# --- PKCS#7 bundle (SignedData, certificates only, RFC 5652 section 5.1) ---
cat "$P/rootA.crt" "$P/intA.crt" > "$P/demo-p7b-input.pem"
$OPENSSL crl2pkcs7 -nocrl -certfile "$P/demo-p7b-input.pem" -out "$OUT/demo-bundle.p7b" 2>/dev/null

# --- Java trust stores (trustedCertEntry, no private keys) -----------------
"$KEYTOOL" -importcert -alias inspector-int -file "$P/intA.crt" \
  -keystore "$OUT/demo-truststore.jks" -storetype JKS -storepass changeit -noprompt >/dev/null
"$KEYTOOL" -importcert -alias inspector-root -file "$P/rootA.crt" \
  -keystore "$OUT/demo-truststore.jks" -storetype JKS -storepass changeit -noprompt >/dev/null
"$KEYTOOL" -importcert -alias inspector-int -file "$P/intA.crt" \
  -keystore "$OUT/demo-truststore.p12" -storetype PKCS12 -storepass changeit -noprompt >/dev/null

# --- README with provenance -------------------------------------------------
COMMIT="$(git -C "$HERE/../../.." rev-parse --short HEAD 2>/dev/null || echo unknown)"
cat > "$OUT/README.md" <<EOF
# Generated fixtures

All files in this directory are produced by \`../gen.sh\` (never hand-edited)
with the real tools below. Private keys are generated in a scratch directory
and deleted; the committed trust stores contain trusted-certificate entries
only.

Tool versions at generation time (recorded on $(date -u +%Y-%m-%d)):

- openssl: $($OPENSSL version)
- keytool: JDK $($KEYTOOL -version 2>&1 | head -1)
- trustinspector commit: $COMMIT

Contents:

| File | What it is |
|---|---|
| demo-root.crt | self-signed RSA-2048 root CA (Inspector Root A) |
| demo-intermediate.crt | intermediate CA, pathlen:0, cross-signed twin A |
| demo-cross-signed.crt | same SPKI as demo-intermediate.crt, twin B |
| demo-leaf.crt | leaf with SANs |
| demo-leaf.der | leaf in DER form |
| demo-bundle.pem | PEM bundle: root + intermediate + leaf |
| demo-negative-serial.crt | certificate with serial -42 (rejected by Go's parser) |
| demo-trusted-reject.pem | CERTIFICATE then TRUSTED CERTIFICATE with \`serverAuth\` reject + alias |
| demo-trusted-alias.pem | TRUSTED CERTIFICATE with alias only |
| demo-bundle.p7b | PKCS#7 SignedData PEM with root + intermediate |
| demo-truststore.jks | JKS trust store (aliases inspector-int, inspector-root; password \`changeit\`) |
| demo-truststore.p12 | PKCS#12 trust store (alias inspector-int; password \`changeit\`) |

Keystore passwords are the public JDK default \`changeit\`; no other secret is
embedded in any fixture.
EOF

echo "fixtures written to $OUT"
ls -la "$OUT"
